# --- images
def png_data(w, h, px):
    raw = b''.join(b'\x00' + bytes(sum(([r, g, b, a] for (r, g, b, a) in px[y*w:(y+1)*w]), [])) for y in range(h))
    def ch(t, d):
        c = struct.pack('>I', len(d)) + t + d
        return c + struct.pack('>I', zlib.crc32(t + d) & 0xffffffff)
    return b'\x89PNG\r\n\x1a\n' + ch(b'IHDR', struct.pack('>IIBBBBB', w, h, 8, 6, 0, 0, 0)) + ch(b'IDAT', zlib.compress(raw)) + ch(b'IEND', b'')
img = png_data(2, 2, [(255,0,0,255), (0,255,0,255), (0,0,255,255), (255,255,0,128)])
b64 = base64.b64encode(img).decode()
C['image-data-png'] = svg('<image x="10" y="10" width="40" height="40" href="data:image/png;base64,%s" style="image-rendering:pixelated"/><image x="55" y="10" width="40" height="20" xlink:href="data:image/png;base64,%s" style="image-rendering:pixelated"/><image x="10" y="60" width="30" height="30" href="data:image/png;base64,%s" preserveAspectRatio="none" style="image-rendering:pixelated"/><image x="50" y="60" width="45" height="30" href="data:image/png;base64,%s" opacity=".5" style="image-rendering:pixelated"/>' % (b64, b64, b64, b64))
